  const btn=$('#createButton'), old=btn.innerHTML; btn.disabled=true; btn.innerHTML=`<span class="spinner"></span> Building ${formatConfig().title.toLowerCase()}…`;
  const input=setupInput();
  const editingId=state.editingProjectId;
