function assetStats(p){const ep=episodeOf(p);const chars=(p?.characters||[]).filter(c=>c.image).length, scenes=(ep?.scenes||[]).filter(s=>s.image).length,totalScenes=(ep?.scenes||[]).length,selected=(ep?.scenes||[]).filter(s=>s.finalIncluded!==false),videos=selected.filter(s=>s.videoUrl).length,selectedScenes=selected.length;return {chars,scenes,videos,totalScenes,selectedScenes,total:chars+scenes+videos,charDone:chars>0&&chars===(p.characters||[]).length,sceneDone:scenes>0&&scenes===totalScenes,videoDone:selectedScenes>0&&videos===selectedScenes}}
function storyTextOf(p,ep=episodeOf(p)){return String(ep?.storyText||'').trim()}
function hasStoryReview(p,ep=episodeOf(p)){return storyTextOf(p,ep).length>=180}
function storyIsApproved(p,ep=episodeOf(p)){return !hasStoryReview(p,ep) || ep?.storyApproved===true}
function storyWordCount(text=''){return String(text).trim()?String(text).trim().split(/\s+/).length:0}
function storyParagraphHtml(text=''){const clean=String(text||'').trim();if(!clean)return '';return clean.split(/\n\s*\n/).filter(Boolean).map(x=>`<p>${esc(x.trim())}</p>`).join('')}
function legacyStorySeed(p,ep){const parts=[p?.title,ep?.title,ep?.synopsis];for(const s of ep?.scenes||[]){parts.push(`Scene ${s.number||''}: ${s.title||''}. ${s.purpose||''} ${s.visual||''} ${dialogueText(s.narration)||''} ${dialogueList(s.dialogue).join(' ')}`)}return parts.filter(Boolean).join('\n\n')}
function projectGenerationInput(p,idea,storySource='full-story'){return {idea:String(idea||'').trim(),storySource,inputMethod:'text',format:p.format||'Story',genre:p.genre||'Open',audience:p.audience||'General',duration:p.duration||formatConfig(p.format).defaultDuration,castSize:p.castSize||'auto',style:p.style||stylePromptFromPreset(p.visualStylePreset||'cinematic-realistic',p.customVisualStyle||''),visualStylePreset:p.visualStylePreset||'cinematic-realistic',customVisualStyle:p.customVisualStyle||'',language:p.language||'English',languageScope:p.languageScope||'entire-story',culturalTreatment:p.culturalTreatment||'auto',sacredRepresentation:p.sacredRepresentation||'auto',languageDirection:p.languageDirection||'',continuityStrength:p.continuityStrength||'strict',controlMode:p.controlMode||'Guided'}}
function renderStoryReview(p,ep){const panel=$('#storyReviewPanel');if(!panel)return;const text=storyTextOf(p,ep),hasReview=hasStoryReview(p,ep),approved=storyIsApproved(p,ep),cfg=formatConfig(p?.format||'Episode');const status=$('#storyReviewStatus'),legacy=$('#storyReviewLegacy'),edit=$('#editFullStory'),rebuild=$('#rebuildFullStory'),approve=$('#approveFullStory'),body=$('#storyReviewText'),meta=$('#storyReviewMeta');$('#storyReviewTitle').textContent=`Review the complete ${cfg.title.toLowerCase()}`;$('#storyReviewCopy').textContent=hasReview?'Read and approve the complete narrative before generating portraits, storyboards, audio or video.':'This older project does not yet contain a full narrative review. Existing production remains available, or you can rebuild a complete story review.';status.textContent=hasReview?(approved?'Approved':'Needs review'):'Legacy project';status.classList.toggle('approved',approved&&hasReview);legacy.classList.toggle('hidden',hasReview);edit.classList.toggle('hidden',!hasReview);rebuild.classList.toggle('hidden',hasReview);approve.classList.toggle('hidden',!hasReview||approved);body.classList.toggle('empty',!hasReview);body.innerHTML=hasReview?storyParagraphHtml(text):`<p>${esc(ep?.synopsis||p?.logline||'No full narrative is stored in this older project.')}</p>`;const words=storyWordCount(text);meta.innerHTML=hasReview?`<span>${words.toLocaleString()} words</span><span>${esc(p.language||'Language open')}</span><span>${esc(p.audience||'Audience open')}</span><span>${esc(p.duration||'Runtime open')}</span>`:`<span>${esc(cfg.title)}</span><span>Created before Story Review</span>`}
function approveCurrentStory(){const p=current(),ep=episodeOf(p);if(!p||!ep||!hasStoryReview(p,ep))return;updateProject(x=>{const e=episodeOf(x);e.storyApproved=true;e.storyApprovedAt=new Date().toISOString()});toast('Story approved. Production tools are ready.')}
async function rebuildStoryReviewFromText(text,button){const p=current(),ep=episodeOf(p);if(!p||!ep)return;const source=String(text||'').trim();if(source.length<80){toast('Add more of the story before rebuilding the production plan.');return}const hasAssets=assetStats(p).total>0||Boolean(p.finalAssembly)||Boolean(p.finalVideoMeta);if(hasAssets&&!confirm('Rebuilding from this story will replace the current cast and scene plan and clear generated production assets for this project. Continue?'))return;const old=button?.textContent;if(button){button.disabled=true;button.textContent='Rebuilding story…'}try{const d=await apiPost('/api/generate-plan',projectGenerationInput(p,source,'full-story'));const next=d.plan;next.id=p.id;next.createdAt=p.createdAt;next.updatedAt=new Date().toISOString();next.archived=p.archived;ensureEpisodeIds(next);next.activeEpisode=1;next.activeEpisodeId=next.episodes[0]?.id||null;if(next.episodes[0])next.episodes[0].storyApproved=false;const idx=state.projects.findIndex(x=>x.id===p.id);state.projects[idx]=next;state.currentId=next.id;save();renderAll();setView('studio');toast('Story rebuilt. Review the complete narrative before production.')}catch(e){toast(e.message||'Could not rebuild the story.')}finally{if(button){button.disabled=false;button.textContent=old||'Save & rebuild'}}}
function openFullStoryEditor(){const p=current(),ep=episodeOf(p);if(!p||!ep)return;const text=storyTextOf(p,ep)||legacyStorySeed(p,ep);$('#modalBody').innerHTML=`<form class="modal-form" id="fullStoryEditorForm"><span class="kicker">STORY REVIEW</span><h2>Edit the complete story</h2><p>Changes are rebuilt into the cast and scene plan so production stays aligned with the story. Nothing is generated until you confirm below.</p><label class="field"><span>Complete story</span><textarea class="story-edit-area" id="fullStoryEditorText" required>${esc(text)}</textarea><small>Keep character names, relationships, cultural context and the ending exactly as you want them.</small></label><div class="modal-actions"><button type="button" class="ghost" id="fullStoryEditorCancel">Cancel</button><button type="submit" class="primary">Save & rebuild plan</button></div></form>`;$('#modal').classList.remove('hidden');$('#fullStoryEditorCancel').onclick=closeModal;$('#fullStoryEditorForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter,txt=$('#fullStoryEditorText').value;closeModal();await rebuildStoryReviewFromText(txt,b)}}
function rebuildLegacyStoryReview(){const p=current(),ep=episodeOf(p);if(!p||!ep)return;rebuildStoryReviewFromText(legacyStorySeed(p,ep),$('#rebuildFullStory'))}
function requireApprovedStory(action='continue'){const p=current(),ep=episodeOf(p);if(storyIsApproved(p,ep))return true;toast(`Review and approve the complete story before you ${action}.`);$('#storyReviewPanel')?.scrollIntoView({behavior:'smooth',block:'start'});return false}
function renderWorkflow(p){const cfg=formatConfig(p?.format||'Episode'),a=assetStats(p),ep=episodeOf(p),approved=storyIsApproved(p,ep),steps=$$('#workflow .workflow-step');steps.forEach(x=>x.classList.remove('done','active'));cfg.journey.forEach((label,i)=>{const t=$(`#wf${i+1}Title`),sub=$(`#wf${i+1}Sub`);if(t)t.textContent=label;if(sub)sub.textContent=cfg.journeySubs[i]||''});let next;if($('#wf1Sub'))$('#wf1Sub').textContent=approved?'Approved':'Review';if(!approved){steps[0]?.classList.add('active');next={title:'Review the complete story',text:'Read, edit if needed, and approve the full narrative before production credits are used.',label:'Review story',action:'review-story'}}else{steps[0]?.classList.add('done');next={title:'Review your cast',text:'Generate or review the recurring characters needed for this production.',label:'Review cast',view:'characters'};if(a.charDone){steps[1]?.classList.add('done');next={title:cfg.title==='Movie'?'Build acts & scenes':'Build the storyboard',text:cfg.title==='Movie'?'Visualize the key scenes across the movie structure.':'Turn each scene into a visual frame while identity references are ready.',label:'Create storyboard',action:'storyboard'}}else steps[1]?.classList.add('active');if(a.sceneDone){steps[2]?.classList.add('done');next={title:'Preview audio',text:`Listen through the ${cfg.finalName} before spending on video generation.`,label:'Preview audio',action:'narrate'}}else if(a.charDone)steps[2]?.classList.add('active');if(p.narrationPlayed){steps[3]?.classList.add('done');next={title:'Generate video',text:'Your story, cast and audio preview are ready for scene rendering.',label:'Generate video',action:'video'}}else if(a.sceneDone)steps[3]?.classList.add('active');if(a.videoDone||p.videoStatus==='ready'){steps[4]?.classList.add('done');next={title:`Prepare final ${cfg.finalName}`,text:`All scene clips are ready. Preview the sequence and lock the final scene order.`,label:'Prepare final',action:'assemble'}}else if(p.narrationPlayed)steps[4]?.classList.add('active');if(p.renderStatus==='ready'||p.renderStatus==='final-video-ready'||p.finalVideoMeta){steps[5]?.classList.add('done');next=p.finalVideoMeta?{title:`Final ${cfg.finalName} ready`,text:'Your single-file final video is ready to download or share.',label:'View final',action:'preview-final'}:{title:`${cfg.title} assembly ready`,text:'The scene order is locked. Render one final video file with approved voices and scene audio.',label:'Render full video',action:'render-final'}}}const card=$('#nextStepCard');if(card){$('#nextStepTitle').textContent=next.title;$('#nextStepText').textContent=next.text;const b=$('#nextStepAction');b.textContent=next.label;b.dataset.nextView=next.view||'';b.dataset.nextAction=next.action||''}}
function normalizedTier(value){const t=String(value||'standard').toLowerCase();if(t==='fast'||t==='draft'||t==='preview')return 'draft';if(t==='premium'||t==='cinematic'||t==='high')return 'premium';return 'standard'}
function tierLabel(value){return {draft:'Draft preview',standard:'Standard',premium:'Premium / Cinematic'}[normalizedTier(value)]}
function tierHint(value){return {draft:'Faster/cheaper when a draft route is configured.',standard:'Balanced default production quality.',premium:'Highest-fidelity route when a premium model is configured.'}[normalizedTier(value)]}
function setSceneTier(index,value){const p=current(),ep=episodeOf(p);if(!ep?.scenes?.[index])return;updateProject(x=>{const e=episodeOf(x);if(e?.scenes?.[index])e.scenes[index].tier=normalizedTier(value)});toast(`Scene quality set to ${tierLabel(value)}.`)}
function normalizedFraming(value){const v=String(value||'safe').toLowerCase();return ['auto','safe','medium','close','wide'].includes(v)?v:'safe'}
function framingLabel(value){return {auto:'Auto',safe:'Safe framing',medium:'Medium shot',close:'Close-up',wide:'Wide shot'}[normalizedFraming(value)]}
function setSceneFraming(index,value){const p=current(),ep=episodeOf(p);if(!ep?.scenes?.[index])return;updateProject(x=>{const e=episodeOf(x);if(e?.scenes?.[index])e.scenes[index].framing=normalizedFraming(value)});toast(`Scene framing set to ${framingLabel(value)}.`)}

function videoCooldownSeconds(scene={}){return Math.max(0,Math.ceil((Number(scene.videoRetryAt||0)-Date.now())/1000))}
function videoButtonLabel(scene={}){return videoCooldownSeconds(scene)>0?'Video temporarily limited':scene.videoUrl?'Regenerate clip':scene.videoOperation?'Rendering…':'Generate video clip'}
function videoButtonDisabled(scene={},productionLocked=false){return productionLocked||videoCooldownSeconds(scene)>0}
function renderStudio(){const p=current();if(!p){$('#studioEmpty').classList.remove('hidden');$('#studioContent').classList.add('hidden');return}$('#studioEmpty').classList.add('hidden');$('#studioContent').classList.remove('hidden');const ep=episodeOf(p),scenes=ep?.scenes||[],stats=assetStats(p),cfg=formatConfig(p.format||'Episode'),episodic=(p.format||'Episode')==='Episode',productionLocked=!storyIsApproved(p,ep);$('#studioTitle').textContent=p.title||'Untitled';$('#studioCrumbTitle').textContent=p.title||'Current project';$('#studioLogline').textContent=p.logline||'';if($('#studioFormatChip'))$('#studioFormatChip').textContent=cfg.title;if($('#studioAudienceChip'))$('#studioAudienceChip').textContent=p.audience||'Audience open';if($('#studioStyleChip'))$('#studioStyleChip').textContent=styleLabel(p.visualStylePreset||'cinematic-realistic');if($('#studioLanguageChip'))$('#studioLanguageChip').textContent=p.language||'Language open';$('#unitLabel').textContent=cfg.unitLabel;$('#episodeNumber').textContent=episodic?String(ep?.number||1).padStart(2,'0'):'';$('#episodeNumber').classList.toggle('hidden',!episodic);$('#episodeTitle').textContent=ep?.title||'Episode';$('#episodeSynopsis').textContent=ep?.synopsis||'';$('#episodeRuntime').textContent=`~${formatTime(scenes.reduce((a,s)=>a+(Number(s.durationSec)||0),0))}`;$('#runtimeLabel').textContent=cfg.runtimeLabel;$('#assetCount').textContent=`${stats.total} asset${stats.total===1?'':'s'}`;const episodesBtn=$('#studioEpisodesBtn'),nextBtn=$('#continueEpisode'),unitsBlock=$('#studioUnitsBlock');if(episodesBtn)episodesBtn.classList.toggle('hidden',!episodic);if(nextBtn)nextBtn.classList.toggle('hidden',!episodic);if(unitsBlock)unitsBlock.classList.toggle('hidden',!episodic);if($('#studioMemoryTitle'))$('#studioMemoryTitle').textContent=cfg.memoryTitle;if($('#sceneProductionTitle'))$('#sceneProductionTitle').textContent=cfg.sceneTitle;
  ensureEpisodeIds(p);$('#studioEpisodes').innerHTML=episodic?(p.episodes||[]).map(e=>`<div class="studio-episode-row"><button class="episode-chip ${e.id===ep?.id?'active':''}" data-studio-episode-id="${esc(e.id)}">${String(e.number).padStart(2,'0')} · ${esc(e.title)}</button>${(p.episodes||[]).length>1?`<button class="episode-mini-delete" data-studio-delete-id="${esc(e.id)}" aria-label="Delete ${esc(e.title)}">×</button>`:''}</div>`).join(''):'';$$('[data-studio-episode-id]').forEach(b=>b.onclick=()=>updateProject(x=>{ensureEpisodeIds(x);x.activeEpisodeId=b.dataset.studioEpisodeId;const e=x.episodes.find(v=>v.id===x.activeEpisodeId);x.activeEpisode=e?.number||x.activeEpisode}));$$('[data-studio-delete-id]').forEach(b=>b.onclick=()=>deleteEpisode(b.dataset.studioDeleteId));
  $('#canonList').innerHTML=(p.worldBible?.canon||[]).map(x=>`<div class="canon-chip">${esc(x)}</div>`).join('')||`<div class="canon-chip">${episodic?'Canon will build as the series grows.':'Project continuity notes will appear here.'}</div>`;
  renderStoryReview(p,ep);
  $('#sceneList').innerHTML=scenes.map((s,i)=>`<article class="scene-card surface"><div class="scene-visual">${s.videoUrl?`<video src="${esc(s.videoUrl)}" controls playsinline preload="metadata"></video>`:s.image?`<img src="${s.image}" alt="${esc(s.title)}">`:`<div class="scene-placeholder"><b>${String(s.number||i+1).padStart(2,'0')}</b><span>Storyboard pending</span></div>`}<div class="asset-tag">${s.videoUrl?'Video ready':s.videoOperation?'Rendering video':s.image?(s.imageMode==='ai'?'Generated art':'Preview art'):'Not generated'}</div></div><div class="scene-copy"><div class="scene-kicker">${p.format==='Movie'&&s.act?`${esc(s.act)} · `:''}SCENE ${String(s.number||i+1).padStart(2,'0')} · ${Number(s.durationSec)||0}s</div><h3>${esc(s.title)}</h3><p>${esc(s.visual||s.purpose||'')}</p><div class="dialogue scene-dialogue-box"><span>${esc(dialogueList(s.dialogue)[0]||dialogueText(s.narration)||'')}</span><button class="dialogue-edit-btn" data-scene-edit="${i}" type="button">Edit performance</button></div><button class="scene-voice-chip" data-scene-voice="${i}" type="button"><span class="scene-voice-icon">🎙</span><span class="scene-voice-copy"><small>Character voice</small><b>${esc(sceneVoiceSummary(p,s))}</b></span><span class="scene-voice-edit">Edit</span></button><div class="scene-meta"><span>🎵 ${esc(s.music||'Open music direction')}</span><span>🔊 ${esc(s.sfx||'Open SFX direction')}</span><span>🎥 ${esc(s.camera||'Open camera direction')}</span></div><label class="scene-final-toggle"><input type="checkbox" data-scene-final-include="${i}" ${s.finalIncluded===false?'':'checked'}><span><b>Include in final</b><small>${s.finalIncluded===false?'Skipped — no video generation required':'Selected for final production'}</small></span></label></div><div class="scene-actions"><div class="scene-action-buttons"><button class="primary small" data-scene-art="${i}" ${productionLocked?'disabled title="Approve the story first"':''}>${s.image?'Regenerate art':'Generate art'}</button><button class="ghost" data-scene-listen="${i}" ${productionLocked?'disabled title="Approve the story first"':''}>▶ Listen</button><button class="ghost" data-scene-video="${i}" ${videoButtonDisabled(s,productionLocked)?`disabled title="${productionLocked?'Approve the story first':'Google video generation is temporarily limited. Try again shortly.'}"`:''}>${videoButtonLabel(s)}</button></div><div class="scene-production-controls"><label class="scene-quality-control" title="${esc(tierHint(s.tier))}"><span>Video quality</span><select data-scene-tier="${i}"><option value="draft" ${normalizedTier(s.tier)==='draft'?'selected':''}>Draft preview</option><option value="standard" ${normalizedTier(s.tier)==='standard'?'selected':''}>Standard</option><option value="premium" ${normalizedTier(s.tier)==='premium'?'selected':''}>Premium / Cinematic</option></select></label><label class="scene-quality-control" title="Controls camera composition for video generation. Safe framing is recommended for normal scenes."><span>Framing</span><select data-scene-framing="${i}"><option value="safe" ${normalizedFraming(s.framing)==='safe'?'selected':''}>Safe framing</option><option value="auto" ${normalizedFraming(s.framing)==='auto'?'selected':''}>Auto</option><option value="medium" ${normalizedFraming(s.framing)==='medium'?'selected':''}>Medium shot</option><option value="close" ${normalizedFraming(s.framing)==='close'?'selected':''}>Close-up</option><option value="wide" ${normalizedFraming(s.framing)==='wide'?'selected':''}>Wide shot</option></select></label></div></div></article>`).join('');
  $$('[data-scene-art]').forEach(b=>b.onclick=()=>generateScene(Number(b.dataset.sceneArt),b));$$('[data-scene-listen]').forEach(b=>b.onclick=()=>listenScene(Number(b.dataset.sceneListen),b));$$('[data-scene-edit]').forEach(b=>b.onclick=()=>openSceneAudioEditor(Number(b.dataset.sceneEdit)));$$('[data-scene-voice]').forEach(b=>b.onclick=()=>{const p=current(),s=episodeOf(p)?.scenes?.[Number(b.dataset.sceneVoice)],idx=sceneVoiceCharacterIndex(p,s);if(idx>=0)openVoicePicker(idx);else openNarratorVoicePicker()});$$('[data-scene-video]').forEach(b=>b.onclick=()=>requestVideo(Number(b.dataset.sceneVideo),b));$$('[data-scene-tier]').forEach(sel=>sel.onchange=()=>setSceneTier(Number(sel.dataset.sceneTier),sel.value));$$('[data-scene-framing]').forEach(sel=>sel.onchange=()=>setSceneFraming(Number(sel.dataset.sceneFraming),sel.value));$$('[data-scene-final-include]').forEach(cb=>cb.onchange=()=>setSceneFinalIncluded(Number(cb.dataset.sceneFinalInclude),cb.checked));renderFinalAssembly(p,ep);renderWorkflow(p);resumePendingVideoPolls();maybeResumeAutoFinal(p)
}

function renderLibrary(){
  const grid=$('#libraryGrid');if(!grid)return;
  const tab=state.libraryTab||'stories';
  $$('#libraryTabs [data-library-tab]').forEach(b=>b.classList.toggle('active',b.dataset.libraryTab===tab));
  const titles={stories:['My Stories','Saved ideas and full stories that do not need to become projects yet.'],characters:['Characters','Reusable cast identities and generated character artwork.'],media:['Media','Generated storyboards, video clips and prepared final assemblies.'],voices:['Voices','Creator-approved and assigned voices currently used across your projects.']};
  const [title,copy]=titles[tab]||titles.stories;if($('#librarySectionTitle'))$('#librarySectionTitle').textContent=title;if($('#librarySectionCopy'))$('#librarySectionCopy').textContent=copy;if($('#libraryNewStory'))$('#libraryNewStory').classList.toggle('hidden',tab!=='stories');
  if(tab==='stories'){
    const drafts=state.savedStories||[];
    if(!drafts.length){grid.innerHTML=`<div class="empty-state surface library-empty"><div class="empty-orb">✎</div><h2>No saved stories yet</h2><p>Save an idea or full story before generating anything. It stays here until you are ready to turn it into an Episode, Short, Story or Movie.</p><button class="primary" data-library-create-story>Save your first story</button></div>`;grid.querySelector('[data-library-create-story]')?.addEventListener('click',()=>setView('create'));return}
    grid.innerHTML=drafts.map(d=>`<article class="story-library-card surface"><div class="story-type"><span>${esc(d.format||'Story')}</span><span>${esc(d.language||'Language open')}</span><span>${esc(d.audience||'Audience open')}</span></div><h3>${esc(d.title||'Untitled story')}</h3><p>${esc(d.idea||'')}</p><div class="story-type"><span>${esc(d.genre||'Open genre')}</span><span>Saved ${new Date(d.updatedAt||d.createdAt||Date.now()).toLocaleDateString()}</span></div><div class="story-library-actions"><button class="primary small" type="button" data-use-story="${esc(d.id)}">Use in Create</button><button class="ghost" type="button" data-duplicate-story="${esc(d.id)}">Duplicate</button><button class="ghost danger" type="button" data-delete-story="${esc(d.id)}">Delete</button></div></article>`).join('');
    $$('[data-use-story]').forEach(b=>b.onclick=()=>loadSavedStory(b.dataset.useStory));$$('[data-duplicate-story]').forEach(b=>b.onclick=()=>duplicateSavedStory(b.dataset.duplicateStory));$$('[data-delete-story]').forEach(b=>b.onclick=()=>deleteSavedStory(b.dataset.deleteStory));return;
  }
  if(tab==='characters'){
    const chars=[];for(const p of state.projects)for(const c of p.characters||[])chars.push({kind:'Character',name:c.name,image:c.image,project:p.title,role:c.role,voice:c.voiceName});
    if(!chars.length){grid.innerHTML=`<div class="empty-state surface library-empty"><div class="empty-orb">◎</div><h2>No characters yet</h2><p>Characters from your productions will appear here for quick reference.</p></div>`;return}
    grid.innerHTML=chars.map((a,i)=>`<button class="asset-card surface" data-lib-character="${i}"><div class="asset-thumb">${a.image?`<img src="${a.image}" alt="${esc(a.name)}">`:`<div class="initials">${esc((a.name||'?').split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</div>`}</div><div class="asset-info"><small>Character · ${esc(a.project||'Project')}</small><b>${esc(a.name)}</b><span>${esc(a.role||'Character')}${a.voice?` · ${esc(a.voice)}`:''}</span></div></button>`).join('');return;
  }
  if(tab==='voices'){
    const voices=[];for(const p of state.projects){if(p.narratorVoiceName)voices.push({name:p.narratorVoiceName,kind:'Narrator',project:p.title,locked:p.narratorVoiceLocked});for(const c of p.characters||[])if(c.voiceName)voices.push({name:c.voiceName,kind:c.name,project:p.title,locked:c.voiceLocked})}
    const unique=[...new Map(voices.map(v=>[`${v.project}|${v.kind}|${v.name}`,v])).values()];if(!unique.length){grid.innerHTML=`<div class="empty-state surface library-empty"><div class="empty-orb">🎙</div><h2>No saved voices yet</h2><p>Assigned and locked character or narrator voices will appear here.</p></div>`;return}
    grid.innerHTML=unique.map(v=>`<article class="story-library-card surface"><div class="story-type"><span>${v.locked?'Locked':'Auto / assigned'}</span><span>${esc(v.project)}</span></div><h3>${esc(v.name)}</h3><p>${esc(v.kind)} voice</p></article>`).join('');return;
  }
  const all=[];for(const p of state.projects){for(const e of p.episodes||[])for(const s of e.scenes||[]){if(s.image)all.push({kind:'Storyboard',name:`${p.title} · ${s.title}`,image:s.image});if(s.videoUrl)all.push({kind:'Video clip',name:`${p.title} · ${s.title}`,video:s.videoUrl})}if(p.finalVideoMeta?.createdAt)all.push({kind:'Final video',name:p.title,finalVideoProjectId:p.id,finalVideoMeta:p.finalVideoMeta});if(p.finalAssembly?.preparedAt)all.push({kind:'Final assembly',name:p.title,assembly:p.finalAssembly})}
  if(!all.length){grid.innerHTML=`<div class="empty-state surface library-empty"><div class="empty-orb">▣</div><h2>No generated media yet</h2><p>Storyboard frames, video clips and final assemblies will appear here.</p></div>`;return}
  grid.innerHTML=all.map((a,i)=>`<button class="asset-card surface" data-asset="${i}"><div class="asset-thumb">${a.video?`<video src="${esc(a.video)}" muted playsinline preload="metadata"></video>`:a.image?`<img src="${a.image}" alt="${esc(a.name)}">`:`<div class="initials">✓</div>`}</div><div class="asset-info"><small class="media-kind-badge">${a.kind}</small><b>${esc(a.name)}</b></div></button>`).join('');$$('[data-asset]').forEach(b=>b.onclick=()=>openLibraryAsset(all[Number(b.dataset.asset)]));
}
function renderAll(){renderUsage();renderProjects();renderCharacters();renderEpisodes();renderStudio();renderLibrary()}

function characterPrompt(p,c){return `Original character reference portrait for an entertainment project. Cultural treatment: ${culturalPrompt(p)}. Sacred representation: ${sacredRepresentationPrompt(p)}. Sacred/cultural identity guidance: ${sacredFigureGuidance(p,c)} Character: ${c.name}. Role: ${c.role}. Age/presentation: ${c.age||'creator-defined'}. Appearance: ${c.appearance||'creator-defined'}. Background/culture/origin: ${c.background||'creator-defined'}. Personality: ${c.personality||''}. Wardrobe: ${c.wardrobe||''}. Visual style: ${characterStyle(p,c)}. ${c.locked!==false?continuityPrompt(p):'Character identity may be reinterpreted because Identity Lock is off.'} If a reference portrait is supplied, treat it as the canonical identity source and change rendering style rather than identity. CLEAN PORTRAIT ONLY: no written words, no captions, no arrows, no callout labels, no infographic annotations, no logos, no celebrity resemblance.`}
function portraitReferenceEntries(p,s){const chars=(p?.characters||[]).filter(c=>c.locked!==false&&typeof c.image==='string'&&c.image.startsWith('data:image/'));if(!s)return chars.slice(0,4).map(c=>({name:c.name,image:c.image}));const sceneText=[s.title,s.visual,s.purpose,dialogueText(s.narration),...dialogueList(s.dialogue)].join(' ').toLowerCase();const mentioned=chars.filter(c=>sceneText.includes(String(c.name||'').toLowerCase()));const ordered=mentioned.length?[...mentioned,...chars.filter(c=>!mentioned.includes(c))]:chars;return ordered.slice(0,4).map(c=>({name:c.name,image:c.image}))}
function scenePrompt(p,ep,s,refs=[]){const cast=(p.characters||[]).map(c=>`${c.name}: ${c.appearance||''}; wardrobe: ${c.wardrobe||'continuity wardrobe'}; identity context: ${sacredFigureGuidance(p,c)}${c.visualStyleOverride&&c.visualStyleOverride!=='project'?`; style override ${characterStyle(p,c)}`:''}`).join(' | ');const refManifest=refs.length?` Reference portraits are supplied in this exact order: ${refs.map((r,i)=>`${i+1}) ${r.name}`).join('; ')}. Each reference image belongs to that named character only; never swap identities between characters.`:'';return `Original storyboard frame. Project: ${p.title}. Format: ${p.format||'Episode'}. Production unit: ${ep.title}. Scene: ${s.title}. Visual action: ${s.visual}. Story purpose: ${s.purpose}. Generation quality: ${tierLabel(s.tier)}. ${tierHint(s.tier)} Cast continuity: ${cast}. Project visual style: ${projectStyle(p)}. Cultural treatment: ${culturalPrompt(p)}. Sacred representation: ${sacredRepresentationPrompt(p)}. ${continuityPrompt(p)}${refManifest} Preserve cultural and geographic details requested by the creator without stereotyping. 16:9 composition. No captions, no written labels, no callout arrows, no infographic annotations, no logos.`}
