async function generateCharacter(i,button,overrides={}){const p=current(),base=p?.characters?.[i];if(!base||!requireApprovedStory('generate character art'))return false;const c={...base,...overrides};const old=button?.textContent;if(button){button.disabled=true;button.textContent='Generating…'}try{const sacred=isSacredCharacter(p,c);const canReuseReference=base.image&&base.locked!==false&&(!sacred||base.sacredReferenceReady===true);const referenceImages=canReuseReference?[base.image]:[];const d=await apiPost('/api/generate-image',{prompt:characterPrompt(p,c),label:c.name,aspect:'1:1',quality:'standard',referenceImages});if(d.mode==='ai')bumpUsage('visual');updateProject(x=>{const target=x.characters[i];target.appearance=c.appearance;target.background=c.background;target.visualStyleOverride=c.visualStyleOverride||'project';target.customVisualStyle=c.customVisualStyle||'';target.image=d.image;target.imageMode=d.mode;target.locked=true;if(sacred&&d.mode==='ai')target.sacredReferenceReady=true});toast(d.mode==='ai'?(canReuseReference?'Alternative portrait generated and identity reference updated.':'Portrait generated and identity locked.'):(d.warning||'Preview portrait shown because live visual generation is unavailable.'));return true}catch(e){toast(e.message);return false}finally{if(button){button.disabled=false;button.textContent=old||'Generate portrait'}}}
