function selectedFinalScenes(ep){return (ep?.scenes||[]).map((s,i)=>({scene:s,index:i})).filter(x=>x.scene.finalIncluded!==false)}
function assemblySceneData(p,ep){return selectedFinalScenes(ep).map(({scene:s,index:i})=>({index:i,number:s.number||i+1,title:s.title||`Scene ${i+1}`,durationSec:Number(s.durationSec)||0,videoUrl:s.videoUrl||null,voiceSummary:sceneVoiceSummary(p,s),music:s.music||'',sfx:s.sfx||''}))}
