  $('#finalAssemblyTitle').textContent=`Prepare final ${cfg.finalName}`;$('#finalReadiness').textContent=`${ready} / ${total} selected clips ready`;
  $('#finalAssemblyCopy').textContent=!total?`No scenes are selected. Include at least one scene, or restore the default selection.`:ready===total?`All selected scenes are ready. You can lock the scene order and render the finished file.`:`${Math.max(0,total-ready)} selected scene clip${total-ready===1?'':'s'} still need video. ${skipped?`${skipped} scene${skipped===1?' is':'s are'} intentionally skipped. `:''}Use Create final video automatically to generate only what is needed.`;
  $('#finalAssemblyScenes').innerHTML=(all||[]).map((scene,i)=>{const included=scene.finalIncluded!==false,failed=job?.errors?.[String(i)];const stateLabel=!included?'— SKIPPED':scene.videoUrl?'✓ READY':failed?'! RETRY':scene.videoOperation?'◌ RENDERING':'○ PENDING';const cls=!included?'skipped':scene.videoUrl?'ready':failed?'failed':'pending';return `<label class="final-scene-item ${cls}"><input type="checkbox" data-final-scene-toggle="${i}" ${included?'checked':''}><span>${stateLabel}</span><b>${String(scene.number||i+1).padStart(2,'0')} · ${esc(scene.title||`Scene ${i+1}`)}</b><small>${Number(scene.durationSec)||0}s planned${scene.videoRoute==='efficient-fallback'?' · Efficient fallback used':''}${failed?` · ${esc(failed)}`:''}</small></label>`}).join('')||'<div class="final-scene-item pending"><b>No scenes yet</b></div>';
  $$('[data-final-scene-toggle]').forEach(cb=>cb.onchange=()=>setSceneFinalIncluded(Number(cb.dataset.finalSceneToggle),cb.checked));
  const prep=$('#prepareFinalAssembly'),preview=$('#previewFinalSequence'),download=$('#downloadAssemblyManifest'),render=$('#renderFinalVideo'),auto=$('#autoFinalVideo'),cancel=$('#cancelAutoFinalVideo');prep.disabled=!approved||!(total&&ready===total);preview.disabled=!ready;download.classList.toggle('hidden',!p.finalAssembly?.preparedAt);if(render)render.disabled=!approved||!(p.finalAssembly?.preparedAt&&total&&ready===total);if(auto){auto.disabled=!approved||!total||state.autoFinalRunning;auto.textContent=state.autoFinalRunning?'Creating final video…':job&&['partial','paused','needs-attention'].includes(job.status)?'Resume final video':'Create final video automatically'}if(cancel)cancel.classList.toggle('hidden',!state.autoFinalRunning);
  const status=$('#finalAssemblyStatus');status.classList.toggle('ready',!!p.finalAssembly?.preparedAt||ready===total&&total>0);let statusText='';if(p.finalVideoMeta?.createdAt)statusText=`Final video rendered ${new Date(p.finalVideoMeta.createdAt).toLocaleString()}. You can download it or share it with installed social apps.`;else if(state.autoFinalRunning){const done=job?.completedCount??ready;statusText=`Automatic production is running · ${done}/${total} selected clips ready${job?.stage?` · ${job.stage}`:''}. You can keep working; completed clips are saved.`}else if(job&&['partial','paused','needs-attention'].includes(job.status)){const failedCount=Object.keys(job.errors||{}).length;statusText=`Automatic production paused with ${ready}/${total} clips ready${failedCount?` and ${failedCount} item${failedCount===1?'':'s'} needing attention`:''}. Click Resume final video to continue only the missing work.`}else if(p.finalAssembly?.preparedAt)statusText=`Final scene order locked ${new Date(p.finalAssembly.preparedAt).toLocaleString()}. Only included scenes are part of the final cut.`;else if(!approved)statusText='Review and approve the complete story before starting production.';else statusText=total&&ready===total?'Ready to prepare final assembly.':'Manual scene generation is optional — Create final video automatically can do the remaining production work for you.';status.textContent=statusText;
