$('#exportProject').onclick=()=>{const p=current();if(!p)return;const blob=new Blob([JSON.stringify(p,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${(p.title||'cinetale-project').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$$('#libraryTabs [data-library-tab]').forEach(b=>b.onclick=()=>{state.libraryTab=b.dataset.libraryTab;renderLibrary()});$('#libraryNewStory').onclick=()=>setView('create');
$('#healthCheckBtn').onclick=async()=>{try{const r=await fetch('/api/health');const d=await r.json();const labels={story:'Story intelligence',image:'Visual generation',voice:'Voice generation',video:'Video generation'};$('#healthResult').innerHTML=Object.entries(d.services||{}).map(([k,v])=>`${v?'●':'○'} ${labels[k]}: <b>${v?'configured':'demo / not configured'}</b>`).join('<br>')}catch{$('#healthResult').textContent='System check unavailable.'}};
$('#ownerCheckBtn').onclick=async()=>{try{const r=await fetch('/api/owner',{headers:{'x-owner-code':$('#ownerCode').value}});const d=await r.json();if(!r.ok)throw new Error(d.error||'Unauthorized');$('#ownerResult').textContent=JSON.stringify(d,null,2);$('#ownerResult').classList.remove('hidden')}catch(e){toast(e.message)}};

for(const p of state.projects){ensureEpisodeIds(p);p.languageScope=p.languageScope||'entire-story';p.culturalTreatment=p.culturalTreatment||'auto';p.sacredRepresentation=p.sacredRepresentation||'auto';p.narratorPerformance=p.narratorPerformance||'Warm';p.narratorPace=p.narratorPace||'Natural';if(p.narratorVoiceLocked==null)p.narratorVoiceLocked=false;for(const c of p.characters||[]){c.voicePerformance=c.voicePerformance||'Natural';c.voicePace=c.voicePace||'Natural';c.voiceMode=c.voiceMode||(c.voiceId?'auto':'auto');if(c.voiceLocked==null)c.voiceLocked=false;c.entityType=c.entityType||'fictional-person';c.representationMode=c.representationMode||'project';c.canonicalVisualCues=Array.isArray(c.canonicalVisualCues)?c.canonicalVisualCues:[]}}save();

$('#accountButton')?.addEventListener('click',()=>openAccountModal('signin'));$('#settingsAccountBtn')?.addEventListener('click',()=>openAccountModal('signin'));$('#settingsSignOutBtn')?.addEventListener('click',signOutAccount);
$('#exportWorkspaceBtn')?.addEventListener('click',exportWorkspace);$('#importWorkspaceBtn')?.addEventListener('click',()=>$('#importWorkspaceFile').click());$('#importWorkspaceFile')?.addEventListener('change',e=>{importWorkspaceFile(e.target.files?.[0]);e.target.value=''});
$('#clearLocalDataBtn')?.addEventListener('click',()=>{if(!confirm('Clear all CineTale projects and saved stories from this browser? Export a backup first if you might need this work again.'))return;if(!confirm('This will permanently remove the local workspace from this browser. Continue?'))return;state.projects=[];state.savedStories=[];state.currentId=null;save();renderAll();toast('Local CineTale workspace cleared.')});
$('#projectSearch')?.addEventListener('input',e=>{state.projectSearch=e.target.value;renderProjects()});$('#projectStatusFilter')?.addEventListener('change',e=>{state.projectStatusFilter=e.target.value;renderProjects()});$('#projectSort')?.addEventListener('change',e=>{state.projectSort=e.target.value;renderProjects()});
loadAuthConfig();

renderAll();
requestAnimationFrame(updateNavIndicator);
